const ASSETS=[
{symbol:'AAPL',name:'Apple Inc.',type:'stock',currency:'USD',themes:['bigtech','dividends'],sector:'Technology'},
{symbol:'MSFT',name:'Microsoft Corp.',type:'stock',currency:'USD',themes:['bigtech','ai','dividends'],sector:'Technology'},
