const BASE={AAPL:23400,MSFT:42600,GOOGL:18200,AMZN:19500,NVDA:12800,META:52000,TSLA:24800,AMD:16400,KO:6300,JNJ:15600,PG:16900,XOM:11400,CVX:15800,SPY:56000,QQQ:49000,VOO:51500,BTC:6800000,ETH:380000};
const DIV=new Set(['AAPL','MSFT','KO','JNJ','PG','XOM','CVX','VOO']);
const BY=Object.fromEntries(ASSETS.map(a=>[a.symbol,a]));
const HOUR=3600000;
function hsym(s){let h=0x811c9dc5;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,0x01000193);}return h>>>0;}
function r01(seed){let t=(seed+0x6d2b79f5)>>>0;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296;}
function noiseAt(sd,n){return r01(sd+Math.imul(n>>>0,0x9e3779b1))*2-1;}
function sn(sd,x){const i=Math.floor(x),f=x-i,u=f*f*(3-2*f);return noiseAt(sd,i)*(1-u)+noiseAt(sd,i+1)*u;}
function ln(sd,x){let s=0,a=1,f=1,n=0;for(let o=0;o<4;o++){s+=sn(sd+o*1013,x*f)*a;n+=a;a*=0.5;f*=2.13;}return s/n;}
function amp(sym){const a=BY[sym];if(a&&a.type==='crypto')return 0.28;if(a&&a.type==='etf')return 0.06;return 0.12;}
function bp(sym){return BASE[sym]!=null?BASE[sym]:10000;}
function priceAt(sym,t){const sd=hsym(sym),x=t/HOUR/24,d=ln(sd,x);return Math.max(1,Math.round(bp(sym)*(1+amp(sym)*d)));}
function mktOpen(sym,now){const a=BY[sym];if(a&&a.type==='crypto')return true;const d=new Date(now),day=d.getUTCDay();if(day===0||day===6)return false;const m=d.getUTCHours()*60+d.getUTCMinutes();return m>=810&&m<1200;}
function quoteFor(sym,now){return{symbol:sym,priceCents:priceAt(sym,now),prevCloseCents:priceAt(sym,now-24*HOUR),ts:new Date(now).toISOString(),marketOpen:mktOpen(sym,now)};}
const RP={'1d':{count:24,step:HOUR},'1w':{count:28,step:6*HOUR},'1m':{count:30,step:24*HOUR},'1y':{count:52,step:7*24*HOUR}};
function candlesFor(sym,range,now){const p=RP[range]||RP['1d'],sd=hsym(sym),out=[];for(let i=p.count-1;i>=0;i--){const tc=now-i*p.step,to=tc-p.step,c=priceAt(sym,tc),o=priceAt(sym,to),b=Math.floor(tc/p.step),wu=Math.abs(noiseAt(sd+7,b))*0.006,wd=Math.abs(noiseAt(sd+13,b))*0.006,hi=Math.round(Math.max(o,c)*(1+wu)),lo=Math.round(Math.min(o,c)*(1-wd));out.push({t:tc,o,h:Math.max(hi,o,c),l:Math.min(lo,o,c),c});}return out;}
function dividendsFor(sym,now){if(!DIV.has(sym))return[];const sd=hsym(sym),dte=5+Math.floor(r01(sd+101)*35),ex=new Date(now+dte*24*HOUR),pay=new Date(ex.getTime()+7*24*HOUR);return[{symbol:sym,exDate:ex.toISOString().slice(0,10),payDate:pay.toISOString().slice(0,10),perShareCents:Math.max(1,Math.round(bp(sym)*0.004*(0.6+r01(sd+202))))}];}
const now=Date.now();
return [{json:{ok:true,ai:true,market:'synthetic'}}];

